package cl.eventpass.processor;
import com.fasterxml.jackson.databind.ObjectMapper; import org.slf4j.*; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import software.amazon.awssdk.auth.credentials.*; import software.amazon.awssdk.regions.Region; import software.amazon.awssdk.services.sqs.SqsClient; import software.amazon.awssdk.services.sqs.model.*;
import java.net.URI; import java.net.http.*; import java.time.Duration;
@Component public class OrderWorker {
 private static final Logger log=LoggerFactory.getLogger(OrderWorker.class); private final SqsClient sqs; private final ObjectMapper mapper=new ObjectMapper(); private final HttpClient http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(3)).build();
 private final String queue=env("SQS_QUEUE_URL","http://localhost:4566/000000000000/ordenes-pendientes"), events=env("EVENTS_URL","http://localhost:8082"), orders=env("ORDERS_URL","http://localhost:8083"), tickets=env("TICKETS_URL","http://localhost:8084");
 public OrderWorker(){sqs=SqsClient.builder().endpointOverride(URI.create(env("SQS_ENDPOINT","http://localhost:4566"))).region(Region.of(env("AWS_REGION","us-east-1"))).credentialsProvider(StaticCredentialsProvider.create(AwsBasicCredentials.create(env("AWS_ACCESS_KEY_ID","test"),env("AWS_SECRET_ACCESS_KEY","test")))).build();}
 private static String env(String k,String d){return System.getenv().getOrDefault(k,d);}
 @Scheduled(fixedDelay=2000) public void poll(){try{var result=sqs.receiveMessage(ReceiveMessageRequest.builder().queueUrl(queue).waitTimeSeconds(1).maxNumberOfMessages(5).visibilityTimeout(30).build());for(Message m:result.messages()){try{process(mapper.readValue(m.body(),OrderMessage.class));sqs.deleteMessage(DeleteMessageRequest.builder().queueUrl(queue).receiptHandle(m.receiptHandle()).build());}catch(Exception e){log.error("Error procesando mensaje; SQS lo reintentará",e);}}}catch(Exception e){log.warn("Cola aún no disponible: {}",e.getMessage());}}
 private void process(OrderMessage m)throws Exception {HttpResponse<String> reserve=send("POST",events+"/api/events/internal/"+m.eventId()+"/reserve?quantity="+m.quantity()+"&orderId="+m.orderId(),"{}");if(reserve.statusCode()==204){String body=mapper.writeValueAsString(new Issue(m.orderId(),m.eventId(),m.buyerId(),m.quantity()));HttpResponse<String> issued=send("POST",tickets+"/api/tickets/internal/issue",body);if(issued.statusCode()<200||issued.statusCode()>=300)throw new IllegalStateException("Tickets respondió "+issued.statusCode()+": "+issued.body());update(m.orderId(),"EMITIDA");log.info("Orden {} emitida",m.orderId());}else if(reserve.statusCode()==409||reserve.statusCode()==404){update(m.orderId(),"RECHAZADA");log.info("Orden {} rechazada: sin aforo o evento inexistente",m.orderId());}else throw new IllegalStateException("Eventos respondió "+reserve.statusCode()+": "+reserve.body());}
 private void update(Long id,String status)throws Exception{HttpResponse<String> r=send("PATCH",orders+"/api/orders/internal/"+id+"/status?value="+status,"");if(r.statusCode()<200||r.statusCode()>=300)throw new IllegalStateException("No se actualizó estado de orden: "+r.statusCode());}
 private HttpResponse<String> send(String method,String url,String body)throws Exception{HttpRequest.Builder b=HttpRequest.newBuilder(URI.create(url)).timeout(Duration.ofSeconds(10)).header("Content-Type","application/json");if(method.equals("POST"))b.POST(HttpRequest.BodyPublishers.ofString(body));else if(method.equals("PATCH"))b.method("PATCH",HttpRequest.BodyPublishers.ofString(body));return http.send(b.build(),HttpResponse.BodyHandlers.ofString());}
 public record OrderMessage(Long orderId,Long eventId,Long buyerId,int quantity){} public record Issue(Long orderId,Long eventId,Long buyerId,int quantity){}
}
